WITH flattened_attrs AS (SELECT id, attributes['device'] AS device, AGGREGATE(items, CAST(0 AS DOUBLE), (acc, li) -> acc + li.qty * li.price, acc -> ROUND(acc, 2)) AS basket_amount, COALESCE(attributes['device'], 'none') AS device_or_default, COALESCE(ship_to.zip, 'UNKNOWN') AS zip_or_unknown, attributes['gift'] AS gift FROM carts) SELECT CASE WHEN basket_amount >= 1420 THEN 'PREMIUM' ELSE 'STANDARD' END AS basket_amount_tier, APPROX_PERCENTILE(basket_amount, 0.5) AS basket_amount_p50, COUNT(DISTINCT id) AS distinct_ids, ROUND(AVG(basket_amount), 2) AS avg_basket_amount FROM flattened_attrs GROUP BY 1
